CREATE TABLE IF NOT EXISTS live_execution_configs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL UNIQUE DEFAULT current_setting('hatchable.user_id', true), enabled boolean NOT NULL DEFAULT true, armed boolean NOT NULL DEFAULT false, broker text NOT NULL DEFAULT 'upstox', product text NOT NULL DEFAULT 'I', order_type text NOT NULL DEFAULT 'MARKET', validity text NOT NULL DEFAULT 'DAY', market_protection integer NOT NULL DEFAULT -1, auto_slice boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now())